import hashlib

# MD5 哈希（不推荐用于密码存储）
def md5_hash(password):
    return hashlib.md5(password.encode()).hexdigest()

# SHA-256 哈希（安全性优于MD5）
def sha256_hash(password):
    return hashlib.sha256(password.encode()).hexdigest()

# 测试对比
password = "admin123"
print(f"MD5: {md5_hash(password)}")
print(f"SHA-256: {sha256_hash(password)}")

import hashlib, os

# 生成随机盐值（16字节）
def generate_salt():
    return os.urandom(16).hex()

# 加盐哈希函数
def salted_hash(password, salt):
    combined = password + salt
    return hashlib.sha256(combined.encode()).hexdigest()

# 使用示例
salt = generate_salt()
hashed = salted_hash("admin123", salt)
print(f"Salt: {salt}")
print(f"Hashed: {hashed}")

import bcrypt

# bcrypt 密码哈希（推荐）
def hash_password_bcrypt(password):
    salt = bcrypt.gensalt(rounds=12)  # 工作因子
    return bcrypt.hashpw(password.encode(), salt)

# 验证密码
def verify_password(password, hashed):
    return bcrypt.checkpw(password.encode(), hashed)

# 使用示例
hashed = hash_password_bcrypt("MySecurePassword")
print(f"bcrypt哈希: {hashed}")

